/// Maps the links of freshly copied clips through the copy's `fresh` ids
/// (old → new); a link whose partner was not copied is cleared (AU-96).
pub(crate) fn relink_copies(clips: &mut [Clip], fresh: &HashMap<u32, u32>) {
    for clip in clips.iter_mut() {
        clip.linked = clip.linked.and_then(|old| fresh.get(&old).copied());
    }
}

impl Project {
    fn unlocked(&self, track: u32) -> bool {
        self.track(track).is_some_and(|t| !t.locked)
    }

    /// The clip `clip` is linked to, when the link is mutual — and so in
    /// the same container, since `Project::clip` searches only this one.
    pub(crate) fn partner(&self, clip: u32) -> Option<&Clip> {
        let named = self.clip(clip)?.linked?;
        if named == clip {
            return None;
        }
        self.clip(named).filter(|c| c.linked == Some(clip))
    }

    /// The named clips in caller order, deduplicated, then each one's
    /// partner on an unlocked track. `Err` on an unknown id, as
    /// `selected_clips` answers.
    pub(crate) fn with_links(&self, clips: &[u32]) -> Result<Vec<u32>, String> {
        self.closure(clips, false)
    }

    /// [`Project::with_links`] for `delete`: a linked SOUND half named
    /// alone adds no partner, so deleting a detached sound keeps its picture
    /// (silent, its link settled away) while deleting a picture takes its
    /// sound (AU-91).
    pub(crate) fn delete_closure(&self, clips: &[u32]) -> Result<Vec<u32>, String> {
        self.closure(clips, true)
    }

    fn closure(&self, clips: &[u32], sound_alone: bool) -> Result<Vec<u32>, String> {
        let named: Vec<&Clip> = self.selected_clips(clips)?;
        let mut out: Vec<u32> = named.iter().map(|c| c.id).collect();
        for clip in named {
            if sound_alone && is_linked_sound(clip) {
                continue;
            }
            if let Some(partner) = self.partner(clip.id) {
                if self.unlocked(partner.track) && !out.contains(&partner.id) {
                    out.push(partner.id);
                }
            }
        }
        Ok(out)
    }

    /// Clears every link that is not mutual inside its own container — the
    /// timeline and each nest apart. `finish` runs it before its identity
    /// comparison, so no op stores a one-sided link and none has to clear
    /// the half it orphaned (AU-96).
    pub(crate) fn settle_links(&mut self) {
        clear_one_sided(&mut self.clips);
        for nest in self.nests.iter_mut() {
            clear_one_sided(&mut nest.clips);
        }
    }

    /// The reader's half of [`Project::settle_links`]: a stored one-sided
    /// link is an `Err`, naming the first clip that holds one.
    pub(crate) fn check_links(&self) -> Result<(), String> {
        let containers = std::iter::once(&self.clips).chain(self.nests.iter().map(|n| &n.clips));
        for clips in containers {
            if let Some((clip, named)) = one_sided(clips).first() {
                return Err(format!(
                    "clip {clip} is linked to clip {named}, which is not linked back"
                ));
            }
        }
        Ok(())
    }

    /// AU-94: a linked clip's speed, direction or speed-naming actions
    /// (start, duration, curve, `end.speed`) may not change. `None` when
    /// `before` is not linked or none of them differ in `after`.
    pub(crate) fn linked_rate_refusal(&self, before: &Clip, after: &Clip) -> Option<String> {
        let partner = before.linked?;
        let same = before.speed == after.speed
            && reversed(before) == reversed(after)
            && speed_actions(before) == speed_actions(after);
        (!same).then(|| linked_rate_sentence(before.id, partner))
    }

    /// An edge edit carried to the partner (AU-93): `edit` applied to
    /// `clip`, then — unless `alone` — the same edit to its partner on an
    /// unlocked track when `carries(clip, partner)` held BEFORE the edit,
//! Placement commit protocol: validate candidate tracks, write placements,
//! mint gained transitions, then return the edit's three-way outcome.
//!
//! It also holds what a placement is built from: `Clip::placed`, the one
//! literal of a freshly placed clip that every adding op overrides by
//! struct update; `Project::add_tracks_behind`, the tracks a placement
//! missing behind its destination inserts at the back; and [`Landing`],
//! unnest's and paste's shared landing — the wanted track, then the
//! fallbacks already added, then a new track in front.

use crate::edit_transition::set_gained_transitions;
use crate::model::{Clip, Enabled, Project, Source};
use crate::outcome::Outcome;
use crate::time::Ticks;

impl Clip {
    /// A freshly placed clip: enabled both ways, ×1, no actions, and every
    /// optional group, transition, name and label absent. Each adding op
    /// overrides what it sets by struct update.
    ///
    /// A field added to [`Clip`] later silently takes this default at every
    /// placing site. That is deliberate: a newly placed clip has none of the
    /// new state. Not a `Default` impl, because a clip with no id, track or
    /// source is not a clip.
    pub(crate) fn placed(
        id: u32,
        track: u32,
        start: Ticks,
        duration: Ticks,
        source: Source,
    ) -> Clip {
        Clip {
            id,
            track,
            start,
            duration,
            source,
            enabled: Enabled::default(),
            speed: 1.0,
            video: None,
            audio: None,
            text: None,
            shape: None,
            graphic: None,
            actions: Vec::new(),
            transition_in: None,
            name: None,
            label: None,
            linked: None,
        }
    }
}

/// Where unnest's and paste's clips land, one clip at a time, in the order
/// the caller places them: the track `depth` back from `base`, then any
/// fallback track already added, then a new track in front. Remembers the
/// tracks it touched, in first-seen order, for `finish_placement`.
pub(crate) struct Landing {
    base: i64,
    fallbacks: Vec<u32>,
    touched: Vec<u32>,
}

impl Landing {
    pub(crate) fn new(base: i64) -> Landing {
        Landing {
            base,
            fallbacks: Vec::new(),
            touched: Vec::new(),
        }
    }

    /// Lands `clip` on the first candidate the overlap rule accepts and
    /// pushes it onto `next`. A fallback track is PUSHED (in front), ordinary.
    pub(crate) fn land(&mut self, next: &mut Project, mut clip: Clip, depth: i64) {
        let wanted = next
            .tracks
            .get((self.base - depth).max(0) as usize)
            .map(|t| t.id);
        let mut chosen: Option<u32> = None;
        for candidate in wanted.into_iter().chain(self.fallbacks.iter().copied()) {
            clip.track = candidate;
            if next
                .check_overlap_rule(std::slice::from_ref(&clip), candidate, &[])
                .is_ok()
            {
                chosen = Some(candidate);
                break;
            }
        }
        // A brand-new track holds nothing, so the last arm always
        // succeeds and the loop always terminates.
        let landed = match chosen {
            Some(id) => id,
            None => {
                let track = next.numbered_track();
                let id = track.id;
                next.tracks.push(track);
                self.fallbacks.push(id);
                id
            }
        };
        clip.track = landed;
        if !self.touched.contains(&landed) {
            self.touched.push(landed);
        }
        next.clips.push(clip);
    }

    /// The tracks a clip landed on, in first-seen order.
    pub(crate) fn touched(&self) -> &[u32] {
        &self.touched
    }
}

impl Project {
    /// Inserts the tracks missing behind a placement's destination: `deepest`
    /// is the deepest depth it lands, `base` the destination's index. Each
    /// is a [`Project::numbered_track`] inserted at index 0, one at a time;
    /// inserting there shifts every existing track up, so the answer is the
    /// destination's index after them, `base` plus their count.
    pub(crate) fn add_tracks_behind(&mut self, deepest: i64, base: i64) -> i64 {
        let deficit = (deepest - base).max(0);
        for _ in 0..deficit {
            let track = self.numbered_track();
            self.tracks.insert(0, track);
        }
        base + deficit
    }

    /// Replace already resolved clips in one draft, checking old tracks
    /// before destination tracks in caller order.
    pub(crate) fn commit_replacements(&self, replacements: Vec<Clip>) -> Result<Outcome, String> {
        let mut tracks = Vec::new();
        for clip in &replacements {
            let old = self.require_clip(clip.id)?.track;
            if !tracks.contains(&old) {
                tracks.push(old);
            }
        }
        for clip in &replacements {
            if !tracks.contains(&clip.track) {
                tracks.push(clip.track);
            }
        }
        for track in &tracks {
            if let Err(why) = self.check_overlap_rule(&replacements, *track, &[]) {
                return Ok(Outcome::Refused(why));
            }
        }

        let mut next = self.clone();
        for replacement in replacements {
            if let Some(slot) = next.clip_mut(replacement.id) {
                *slot = replacement;
            }
        }
        self.finish_placement(next, &tracks)
    }

    /// Append caller-allocated clips to a private draft after checking the
    /// input project. The draft may already contain new tracks or incidental
    /// property changes, but none of the added clips.
    pub(crate) fn commit_additions(
        &self,
        mut next: Project,
        additions: Vec<Clip>,
    ) -> Result<Outcome, String> {
        let mut tracks = Vec::new();
        for clip in &additions {
            if !tracks.contains(&clip.track) {
                tracks.push(clip.track);
            }
        }
        for track in &tracks {
            if let Err(why) = self.check_overlap_rule(&additions, *track, &[]) {
                return Ok(Outcome::Refused(why));
            }
        }
        next.clips.extend(additions);
        self.finish_placement(next, &tracks)
    }

    /// Complete a placement after its caller has chosen its exact tracks.
    /// No overlap check or early identity belongs here: even a zero-distance
    /// move can gain a transition on an affected track.
    pub(crate) fn finish_placement(
        &self,
        mut next: Project,
        tracks: &[u32],
    ) -> Result<Outcome, String> {
        set_gained_transitions(&mut next, tracks);
        self.finish(next)
    }

    /// The single exit of every op: a result equal to the input is
    /// [`Outcome::Identity`] (never a copy, which would register a phantom
    /// undo step), and a result that broke an invariant is an `Err` rather
    /// than a project the rest of the crate cannot reason about.
    ///
    /// It never answers [`Outcome::Refused`]: a rule that says no does so
    /// where it is asked, with its own sentence, before anything is built
    /// for this to judge.
    ///
    /// Links settle FIRST (`edit_link.rs`, spec §11 AU-96): a link whose
    /// partner the op removed, nested or replaced is cleared here, so no op
    /// stores a one-sided link and the comparison sees the settled result.
    pub(crate) fn finish(&self, mut next: Project) -> Result<Outcome, String> {
        next.settle_links();
        if next == *self {
            return Ok(Outcome::Identity);
        }
        next.validate()?;
        Ok(Outcome::Applied(next))
    }
}
    /// count the way `add_track` names one, so inserting it behind the stack
    /// does not renumber the tracks above. Does not insert it: the caller
    /// chooses where (behind the stack, or in front).
    pub(crate) fn numbered_track(&mut self) -> Track {
        let id = self.allocate_id();
        Track::ordinary(id, self.next_track_name())
    }

    /// Gives a copied clip fresh ids: the clip's own, then each action's in
    /// vector order. Actions move with the clip, and an action id is unique
    /// project-wide, so a copy that kept them would collide.
    pub(crate) fn remint(&mut self, clip: &mut Clip) {
        clip.id = self.allocate_id();
        for action in &mut clip.actions {
            action.id = self.allocate_id();
        }
    }

