impl Project {
    /// Merges `patch` into every named clip's video props (spec §6).
    /// An identity when nothing changes; `Err` for an unknown clip, a clip
    /// with no video props, an unknown key, or a value out of range.
    pub fn set_video(&self, clips: &[u32], patch: &Value) -> Result<Outcome, String> {
        self.patch_clips(clips, patch, Group::Video)
    }

    /// Merges `patch` into every named clip's audio props (spec §6). A patch
    /// setting `duck.mode` to `speech` is refused on a clip that is not a
    /// media clip or whose media has no `speech` (spec §11 AU-111).
    pub fn set_audio(&self, clips: &[u32], patch: &Value) -> Result<Outcome, String> {
        self.patch_clips(clips, patch, Group::Audio)
    }

    /// Whether `clip` is a media clip whose media carries `speech`.
    fn has_speech(&self, clip: &Clip) -> bool {
        let Source::Media { media, .. } = clip.source else {
            return false;
        };
        self.media(media).is_some_and(|m| m.speech.is_some())
    }

    /// Merges `patch` into every named text clip's text props (spec §6).
    pub fn set_text(&self, clips: &[u32], patch: &Value) -> Result<Outcome, String> {
        self.patch_clips(clips, patch, Group::Text)
        let Some(animation) = props.animation.as_mut() else {
            return;
        };
        animation.r#in = self.snapped(animation.r#in);
        animation.out = self.snapped(animation.out);
    }

    /// The chain that makes a video group storable — `set_video`'s and every
    /// pasted video group's (issue #349), so a group written by hand into a
    /// clipboard payload meets exactly what a patch meets, in the same
    /// order and with the same sentences.
    ///
    /// 1. **One spelling of "no motion"** (format version 8, road map 5
    ///    §5a): a patch that clears the last filled slot leaves a `Motion`
    ///    with three `None`s behind, and a payload's `{"motion": {}}` or
    ///    three explicit nulls deserialise to the same thing; either would
    ///    round-trip as `{"in": null, "out": null, "during": null}` and make
    ///    two equal clips compare unequal. It is normalised HERE rather than
    ///    in serde, because the deep merge is what produces the empty one —
    ///    a caller who writes `{"motion": {}}` means the same thing and gets
    ///    the same answer. The invariant stays open only at the FILE reader,
    ///    which keeps the long spelling on purpose until a patch touches it
    ///    (`core/tests/schema_v8.rs`'s
    ///    `a_motion_whose_slots_are_all_cleared_normalises_back_to_null`;
    ///    road map 7 §2.2).
    /// 2. The vocabulary's ranges (`check_video`), on the values the caller
    ///    sent.
    /// 3. An identity curve is stored as none (spec §11 GR-12), AFTER the
    ///    range check so a malformed identity-shaped curve is still refused
    ///    by name; an identity curve on an uncurved clip is then an identity.
    /// 4. The rules about this CLIP rather than the values — [`check_blend`],
    ///    the adjustment and qualifier rules, the cutout's clip kinds (spec
    ///    §11 CO-20), Behind Subject's (CO-52), motion blur's (CU-111), the
    ///    look's media.
    /// 5. Motion timings snapped to the grid ([`Self::snap_motion`]).
    ///
    /// The look's own normalisation (`normalise_look`) is the patch path's
    /// alone: it reads the PATCH, which a pasted group does not have.
    pub(crate) fn settle_video(&self, clip: &Clip, props: &mut VideoProps) -> Result<(), String> {
        if props.motion.is_some_and(|motion| motion.is_empty()) {
            props.motion = None;
        }
        check_video(props, self.source_size(clip))?;
        props.curves.drop_identities();
        check_blend(clip, props)?;
        check_adjustment_video(clip, props)?;
        check_qualifier_clip(clip, props)?;
        crate::cutout_check::check_cutout_clip(clip, props)?;
        crate::cutout_check::check_behind_subject_clip(clip, props)?;
        crate::motion_blur::check_motion_blur_clip(clip, props)?;
        self.check_hide_silent_clip(clip, props)?;
        self.check_look_media(props)?;
        self.snap_motion(props);
        Ok(())
    }

    /// What `paste_attributes` runs on each group it has just replaced, and
    /// `paste` on every group of every clip it lands
    /// ([`Self::normalise_and_check_pasted`]), so a payload written by hand
    /// meets the bounds a patch does and a group `paste_attributes` did not
    /// touch is not its business. A video group goes through
    /// [`Self::settle_video`], `set_video`'s own chain; the other three
    /// through the same `check_audio` / `check_text` / `check_shape` the
    /// patch path calls, a text group's timings then snapped to the
    /// destination grid. A group the clip lacks has nothing to check.
    pub(crate) fn normalise_and_check_group(
        &self,
        clip: &mut Clip,
        group: Group,
    ) -> Result<(), String> {
        match group {
            Group::Video => {
                if let Some(mut video) = clip.video.clone() {
                    self.settle_video(clip, &mut video)?;
                    clip.video = Some(video);
                }
            }
            Group::Audio => {
                if let Some(audio) = clip.audio.as_ref() {
                    check_audio(audio)?;
                }
            }
            Group::Text => {
                if let Some(text) = clip.text.as_mut() {
                    check_text(text)?;
                    self.snap_animation(text);
                }
            }
            Group::Shape => {
                if let Some(shape) = clip.shape.as_ref() {
                    check_shape(shape)?;
                }
            }
        }
        Ok(())
    }

    /// The clip's speed against `SPEED_MIN`–`SPEED_MAX`, then every group of
    /// one clip `paste` is about to land, through
    /// [`Self::normalise_and_check_group`] in [`GROUPS`] order, so a payload
    /// written by hand meets the bounds a patch does (issue #62, #206). A
    /// failure names the id the PAYLOAD gave the clip, the only one its
    /// writer knows. The callers have already reset a non-finite or
    /// non-positive speed to 1. The clip's own times are the caller's to
    /// re-snap, after this, at the speed checked here.
    pub(crate) fn normalise_and_check_pasted(
        &self,
        clip: &mut Clip,
        payload_id: u32,
    ) -> Result<(), String> {
        // Spelled as JSON spells it, as `validate`'s speed sentence is.
        if !(SPEED_MIN..=SPEED_MAX).contains(&clip.speed) {
            return Err(format!(
                "pasted clip {payload_id}: speed {} is outside ×{SPEED_MIN}–×{SPEED_MAX}",
                serde_json::Value::from(clip.speed)
            ));
        }
        for group in GROUPS {
            self.normalise_and_check_group(clip, group)
                .map_err(|why| format!("pasted clip {payload_id}: {why}"))?;
        }
        Ok(())
    }

    /// The one implementation behind the four `set_*` property ops: merge,
    /// check the keys against the group's schema, deserialize, range-check,
    /// store.
    ///
    /// A clip that does not HAVE the group is an error, not a silent skip:
    /// the group's presence is what "this clip has audio" / "this is a text
    /// clip" means, and inventing it would put text props on a video clip.
    fn patch_clips(&self, clips: &[u32], patch: &Value, group: Group) -> Result<Outcome, String> {
        if !patch.is_object() {
            return Err(format!(
                "{} patch must be a json object, not {}",
                group.name(),
                describe(patch)
            ));
        }
        let ids: Vec<u32> = self.selected_clips(clips)?.iter().map(|c| c.id).collect();
        if ids.is_empty() {
            return Ok(Outcome::Identity);
        }

        let mut next = self.clone();
        for id in ids {
            let clip = match next.clip(id) {
                Some(clip) => clip.clone(),
                None => continue,
            };
            match group {
                Group::Video => {
                    let base = clip
                        .video
                        .clone()
                        .ok_or_else(|| format!("clip {id} has no video properties"))?;
    /// Whether `instance` is an adjustment clip on a top-level matte track,
    /// which draws nothing and cuts nothing (this module's doc): the recipe
    /// drops it before `frame_mattes` sees it.
    pub(crate) fn inert_adjustment(&self, instance: &Instance) -> bool {
        is_adjustment(instance.clip)
            && instance.inside.is_empty()
            && !instance.track.matte.is_none()
    }
}

/// Whether the clip is an adjustment clip.
pub(crate) fn is_adjustment(clip: &Clip) -> bool {
    matches!(clip.source, Source::Adjustment)
}

/// The one rule about an adjustment CLIP's video group: no neighbourhood
/// filter and no blend mode. An `Err`, as `check_blend`'s is, so `paste` and
/// `paste_attributes` meet it through `settle_video` and refuse the whole
/// paste. Any other clip passes.
pub(crate) fn check_adjustment_video(clip: &Clip, props: &VideoProps) -> Result<(), String> {
    if !is_adjustment(clip) {
        return Ok(());
    }
    for filter in &props.filters {
        let name = match filter.kind {
            FilterKind::Blur => "blur",
            FilterKind::Sharpen => "sharpen",
            FilterKind::Pixelate => "pixelate",
